export const studioVoices=['marin','cedar','alloy','ash','ballad','coral','echo','fable','nova','onyx','sage','shimmer','verse'];
export function speechChunks(text,max=1200){const chunks=[];let current='';for(const word of String(text).trim().split(/\s+/)){if(!word)continue;if(current.length+word.length+1>max){if(current)chunks.push(current);current='';}let rest=word;while(rest.length>max){let end=max;if(/[\uD800-\uDBFF]/.test(rest[end-1]))end--;chunks.push(rest.slice(0,end));rest=rest.slice(end);}current+=(current?' ':'')+rest;}if(current)chunks.push(current);return chunks;}
export function rankedVoices(voices,lang='en'){return [...voices].sort((a,b)=>{const rank=v=>(v.lang?.split('-')[0]===lang.split('-')[0]?100:0)+(/premium|enhanced|natural|neural/i.test(v.name+' '+v.quality)?20:0)+(v.localService?2:0);return rank(b)-rank(a)||a.name.localeCompare(b.name);});}
export async function deviceVoices(host=globalThis.window?.BookWizHost,synth=globalThis.window?.speechSynthesis){if(host?.speechVoices)return host.speechVoices();if(!synth)return [];const list=synth.getVoices();if(list.length)return list;return new Promise(resolve=>{let timer;const done=()=>{clearTimeout(timer);synth.removeEventListener?.('voiceschanged',done);resolve(synth.getVoices());};synth.addEventListener?.('voiceschanged',done,{once:true});timer=setTimeout(done,900);});}
async function fetchSpeech(connection,key,text,voice,{signal,fetcher=globalThis.fetch}={}){if(!studioVoices.includes(voice))throw Error('Choose an available narration voice.');const endpoint=connection.endpoint.replace(/\/$/,'')+'/audio/speech';const result=await fetcher(endpoint,{method:'POST',headers:{'Authorization':'Bearer '+key,'Content-Type':'application/json'},body:JSON.stringify({model:'gpt-4o-mini-tts',voice,input:text,response_format:'mp3',instructions:'Read as a thoughtful audiobook narrator, with natural phrasing, clear articulation and restrained emotion. Preserve the language of the text.'}),signal});if(!result.ok){if(result.status===401||result.status===403)throw Error('This connection cannot use OpenAI speech. Check its key and audio-model access.');if(result.status===429)throw Error('OpenAI speech reached a rate or credit limit. Try again later.');throw Error('The narration service could not finish this passage. Try again.');}const blob=await result.blob();if(!blob.size||blob.size>20*1024*1024)throw Error('The narration response could not be played.');return blob;}
export class Narrator{
 constructor({onState=()=>{},synth=globalThis.window?.speechSynthesis,Utterance=globalThis.SpeechSynthesisUtterance,host=globalThis.window?.BookWizHost,AudioType=globalThis.Audio,url=globalThis.URL}={}){Object.assign(this,{onState,synth,Utterance,host,AudioType,url});this.state='idle';this.token=0;this.index=0;}
 notify(state,message=''){this.state=state;this.onState({state,message,index:this.index,total:this.chunks?.length||0});}
 async start(text,options={}){this.stop();this.options=options;this.chunks=speechChunks(text);this.index=0;if(!this.chunks.length)throw Error('Write a passage before reading aloud.');const token=++this.token;this.abort=new AbortController();try{for(;this.index<this.chunks.length;this.index++){if(token!==this.token)return;this.notify(options.engine==='cloud'?'loading':'playing');if(options.engine==='cloud'){const blob=await options.cloud(this.chunks[this.index],this.abort.signal);if(token!==this.token)return;await this.playAudio(blob,token);}else if(this.host?.speakText){await this.host.speakText({text:this.chunks[this.index],voice:options.voice,rate:options.rate,lang:options.lang});}else{await this.playDevice(this.chunks[this.index],options);}if(token!==this.token)return;}this.notify('idle','Reading complete.');}catch(error){if(token===this.token)this.notify('error',error.message||'This voice could not read the passage. Choose another voice.');}finally{if(token===this.token){this.release();this.options=null;this.chunks=[];this.cancelWait=null;this.abort=null;}}}
 playDevice(text,options){if(!this.synth||!this.Utterance)throw Error('Device voices are unavailable here. Choose Studio narration or use an installed app.');return new Promise((resolve,reject)=>{this.cancelWait=resolve;const u=new this.Utterance(text);u.lang=options.lang;u.rate=options.rate||1;u.voice=this.synth.getVoices().find(v=>v.voiceURI===options.voice)||null;u.onend=resolve;u.onerror=e=>reject(Error(e.error==='not-allowed'?'Allow speech playback, then try again.':'This device voice could not finish. Choose another voice.'));this.synth.speak(u);});}
 playAudio(blob,token){return new Promise((resolve,reject)=>{this.cancelWait=resolve;this.release();this.audio=new this.AudioType();this.audio.preload='auto';this.audio.playbackRate=this.options.rate||1;this.audioURL=this.url.createObjectURL(blob);this.audio.src=this.audioURL;this.audio.onended=resolve;this.audio.onerror=()=>reject(Error('The audio could not be played. Try another voice.'));this.audio.play().then(()=>{if(token===this.token)this.notify('playing');}).catch(e=>{if(token!==this.token){resolve();return;}if(e.name==='NotAllowedError')this.notify('paused','Tap Resume to allow audio playback.');else reject(e);});});}
 pause(){if(!['playing','loading'].includes(this.state))return;if(this.state==='loading')return;if(this.audio)this.audio.pause();else if(this.host?.pauseSpeech)this.host.pauseSpeech();else this.synth?.pause();this.notify('paused');}
 resume(){if(this.state!=='paused')return;if(this.audio){const token=this.token;this.audio.play().then(()=>{if(token===this.token)this.notify('playing');}).catch(()=>{if(token===this.token)this.notify('error','Playback could not resume. Start reading again.');});}else{if(this.host?.resumeSpeech)this.host.resumeSpeech();else this.synth?.resume();this.notify('playing');}}
 release(){if(this.audio){this.audio.pause();this.audio.src='';this.audio=null;}if(this.audioURL){this.url.revokeObjectURL(this.audioURL);this.audioURL=null;}}
 stop(){this.token++;this.abort?.abort();this.synth?.cancel();this.host?.stopSpeech?.();this.cancelWait?.();this.cancelWait=null;this.release();this.options=null;this.chunks=[];this.index=0;this.notify('idle');}
}

export async function openAISpeech(connection,key,text,voice,{signal,fetcher=globalThis.fetch}={}){const controller=new AbortController(),cancel=()=>controller.abort();if(signal?.aborted)cancel();signal?.addEventListener('abort',cancel,{once:true});const timer=setTimeout(cancel,90000);try{return await fetchSpeech(connection,key,text,voice,{signal:controller.signal,fetcher});}catch(error){if(controller.signal.aborted&&!signal?.aborted)throw Error('Narration took too long. Try a short sample or another voice.');throw error;}finally{clearTimeout(timer);signal?.removeEventListener('abort',cancel);}}
